import numpy as np
def rd(f):
    L=open(f).read().split('\n'); n=int(L[0]); sym=[];xyz=[]
    for l in L[2:2+n]:
        p=l.split(); sym.append(p[0]); xyz.append([float(x) for x in p[1:4]])
    return sym,np.array(xyz)
sym,xyz=rd('opt2.xyz')
def ang(a,b,c):
    v1=xyz[a]-xyz[b]; v2=xyz[c]-xyz[b]
    return np.degrees(np.arccos(v1.dot(v2)/np.linalg.norm(v1)/np.linalg.norm(v2)))
